from __future__ import annotations

import json
from pathlib import Path
from typing import Any

PAGE_TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Factorio Technology Cost Planner</title>
<style>
:root{color-scheme:light;--bg:#f4f6f8;--panel:#fff;--ink:#17212b;--muted:#586777;--line:#d7dee5;--accent:#b75b21}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.45 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:32px 20px 56px}h1{margin:0 0 6px;font-size:2rem}h2{font-size:1.2rem;margin:0 0 14px}.subtitle,.muted{color:var(--muted)}.layout{display:grid;grid-template-columns:minmax(260px,1fr) minmax(320px,1.35fr);gap:20px;margin-top:24px}section,.summary-card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:20px}label{font-weight:650;display:block;margin-bottom:7px}input{font:inherit;border:1px solid #aeb9c4;border-radius:6px;padding:10px 12px;width:100%}.results{margin-top:8px;max-height:52vh;overflow:auto;border:1px solid var(--line);border-radius:6px}.result{width:100%;display:flex;justify-content:space-between;gap:12px;text-align:left;padding:10px 12px;border:0;border-bottom:1px solid var(--line);background:#fff;color:inherit;font:inherit;cursor:pointer}.result:hover{background:#fff3e9}.result small{color:var(--muted)}.selected{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px}.chip{display:flex;align-items:center;gap:8px;background:#fff3e9;border:1px solid #ebc7ab;border-radius:6px;padding:5px 8px 5px 12px}.chip button{border:0;width:26px;height:26px;cursor:pointer;background:#fff;color:#8c3f12;font-size:18px}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.summary-card{padding:14px}.summary-card strong{display:block;font-size:1.25rem}.summary-card span{color:var(--muted);font-size:.9rem}table{width:100%;border-collapse:collapse;margin:14px 0 0}th,td{text-align:left;padding:9px 7px;border-bottom:1px solid var(--line)}th:last-child,td:last-child{text-align:right}.empty{color:var(--muted);padding:16px 2px}.included{margin:20px 0 0;padding-left:22px;color:var(--muted)}.included li{padding:3px 0}@media(max-width:760px){.layout{grid-template-columns:1fr}.results{max-height:38vh}.summary{grid-template-columns:1fr}}
</style><style>.page-header{display:flex;justify-content:space-between;align-items:center;gap:16px}.mod-switch{display:flex;border:1px solid var(--line);border-radius:5px;overflow:hidden}.mod-switch button{font:inherit;cursor:pointer;border:0;border-right:1px solid var(--line);background:#fff;padding:8px 12px}.mod-switch button:last-child{border:0}.mod-switch button[aria-pressed=true]{background:var(--ink);color:#fff}.tool-link{display:inline-block;margin-top:8px;color:var(--accent);font-weight:650;text-underline-offset:3px}@media(max-width:600px){.page-header{align-items:flex-start;flex-direction:column}}</style>
</head>
<body><main>
<div class="page-header"><h1>Factorio Technology Cost Planner</h1><div class="mod-switch" role="group" aria-label="Factorio data set"><button type="button" data-mod="base">Base</button><button type="button" data-mod="space-age">Space Age</button></div></div>
<p class="subtitle">Search in English, add technologies, and see the combined science cost of each technology and its prerequisites. Shared prerequisites count once.</p>
<a class="tool-link" href="factorio-crafting.html">Open the Crafting Mall Planner</a>
<div class="layout"><section><h2>Find a technology</h2><label for="search">Technology name</label><input id="search" type="search" autocomplete="off"><div id="results" class="results" aria-live="polite"></div></section>
<section><h2>Your plan</h2><div id="selected" class="selected"></div><div id="level-control" hidden><label for="levels">Levels for each infinite technology</label><input id="levels" type="number" min="1" max="1000" value="1"></div><div id="summary"></div><div id="included"></div></section></div>
</main><script>
const datasets=__TECHNOLOGIES__, defaultMod=__DEFAULT_MOD__, selectedNames=new Set();
let modSet=defaultMod, technologies=datasets[defaultMod];
const search=document.getElementById('search'), results=document.getElementById('results'), selected=document.getElementById('selected'), summary=document.getElementById('summary'), included=document.getElementById('included'), levelControl=document.getElementById('level-control'), levelsInput=document.getElementById('levels');
function setDataset(next){if(!datasets[next])return;modSet=next;technologies=datasets[next];for(const name of selectedNames)if(!technologies[name])selectedNames.delete(name);document.querySelectorAll('.mod-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mod===next)));render()}
function isInfinite(t){return t.maxLevel==='infinite'||t.countFormula!==null}
function formulaCount(formula,level){const tokens=formula.match(/\s*(?:\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|L|[()+\-*/^])/gy)?.map(x=>x.trim());if(!tokens||tokens.join('').replace(/\s/g,'')!==formula.replace(/\s/g,''))throw Error('Unsupported count formula');let p=0;function primary(){const x=tokens[p++];if(x==='('){const v=expression();if(tokens[p++]!==')')throw Error('Unclosed formula');return v}if(x==='L')return level;if(x&&/^\d/.test(x))return Number(x);throw Error('Unsupported count formula')}function power(){const v=primary();return tokens[p]==='^'?(p++,v**unary()):v}function unary(){if(tokens[p]==='+'){p++;return unary()}if(tokens[p]==='-'){p++;return -unary()}return power()}function product(){let v=unary();while(tokens[p]==='*'||tokens[p]==='/'){const op=tokens[p++],r=unary();v=op==='*'?v*r:v/r}return v}function expression(){let v=product();while(tokens[p]==='+'||tokens[p]==='-'){const op=tokens[p++],r=product();v=op==='+'?v+r:v-r}return v}const v=expression();if(p!==tokens.length||!Number.isFinite(v)||v<0)throw Error('Invalid formula');return v}
function countFor(t,n){if(t.countFormula){let total=0;for(let l=t.initialLevel;l<t.initialLevel+n;l++)total+=formulaCount(t.countFormula,l);return total}if(t.count===null)return 0;return typeof t.maxLevel==='number'?t.count*t.maxLevel:t.count}
function ancestors(){const found=new Set();function visit(name){if(found.has(name))return;found.add(name);technologies[name]?.prerequisites.forEach(visit)}selectedNames.forEach(visit);return [...found].filter(n=>technologies[n]).sort((a,b)=>technologies[a].label.localeCompare(technologies[b].label))}
const fmt=n=>new Intl.NumberFormat(undefined,{maximumFractionDigits:2}).format(n);
function renderSearch(){const q=search.value.trim().toLocaleLowerCase(), matches=Object.values(technologies).filter(t=>!selectedNames.has(t.name)&&(!q||t.label.toLocaleLowerCase().includes(q)||t.name.toLowerCase().includes(q))).sort((a,b)=>a.label.localeCompare(b.label)).slice(0,40);results.replaceChildren();if(!matches.length){results.textContent=q?'No matching technologies.':'Type to search available technologies.';return}for(const t of matches){const b=document.createElement('button');b.className='result';b.type='button';const label=document.createElement('span'),key=document.createElement('small');label.textContent=t.label;key.textContent=t.name;b.append(label,key);b.onclick=()=>{selectedNames.add(t.name);search.value='';render();search.focus()};results.append(b)}}
function render(){selected.replaceChildren();for(const name of [...selectedNames].sort((a,b)=>technologies[a].label.localeCompare(technologies[b].label))){const chip=document.createElement('span'),text=document.createElement('span'),remove=document.createElement('button');chip.className='chip';text.textContent=technologies[name].label;remove.textContent='×';remove.title='Remove technology';remove.setAttribute('aria-label','Remove '+technologies[name].label);remove.onclick=()=>{selectedNames.delete(name);render()};chip.append(text,remove);selected.append(chip)}const names=ancestors(), hasInfinite=names.some(n=>isInfinite(technologies[n]));levelControl.hidden=!hasInfinite;const level=Math.max(1,Math.min(1000,parseInt(levelsInput.value,10)||1));levelsInput.value=String(level);const science=new Map();let seconds=0;for(const name of names){const t=technologies[name], count=countFor(t,isInfinite(t)?level:1);for(const ingredient of t.ingredients)science.set(ingredient.name,(science.get(ingredient.name)||0)+ingredient.amount*count);if(t.time!==null)seconds+=t.time*count}summary.replaceChildren();included.replaceChildren();if(!selectedNames.size){summary.textContent='Add one or more technologies to see their total cost.';renderSearch();return}const cards=document.createElement('div');cards.className='summary';for(const [value,title] of [[fmt([...science.values()].reduce((a,b)=>a+b,0)),'Total science packs'],[fmt(seconds)+' s','Research time'],[String(names.length),'Technologies including prerequisites']]){const card=document.createElement('div'),strong=document.createElement('strong'),span=document.createElement('span');card.className='summary-card';strong.textContent=value;span.textContent=title;card.append(strong,span);cards.append(card)}summary.append(cards);if(science.size){const table=document.createElement('table'),body=document.createElement('tbody');table.innerHTML='<thead><tr><th>Science pack</th><th>Quantity</th></tr></thead>';for(const [name,amount] of [...science].sort((a,b)=>(technologies[a[0]]?.label||a[0]).localeCompare(technologies[b[0]]?.label||b[0]))){const row=document.createElement('tr'),item=document.createElement('td'),quantity=document.createElement('td');item.textContent=technologies[name]?.label||name;quantity.textContent=fmt(amount);row.append(item,quantity);body.append(row)}table.append(body);summary.append(table)}const heading=document.createElement('h2'),list=document.createElement('ul');heading.textContent='Included technologies';list.className='included';for(const name of names){const item=document.createElement('li');item.textContent=technologies[name].label+' ('+name+')';list.append(item)}included.append(heading,list);renderSearch()}
document.querySelectorAll('.mod-switch button').forEach(button=>button.addEventListener('click',()=>setDataset(button.dataset.mod)));search.addEventListener('input',renderSearch);levelsInput.addEventListener('input',render);document.querySelectorAll('.mod-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mod===modSet)));render();
</script></body></html>'''


def write_technology_page(datasets: dict[str, dict[str, Any]], output: Path, default_mod: str = "base") -> None:
    payload = json.dumps(datasets, ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    html = PAGE_TEMPLATE.replace("__TECHNOLOGIES__", payload).replace("__DEFAULT_MOD__", json.dumps(default_mod))
    output.write_text(html, encoding="utf-8")
